import{_ as i,o as t,a as n,b as o}from"./app.C41L12d5.js";const s="/ascendc.github.io/assets/tiling_dataflow.D_nQgk2A.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"异构计算","link":"/guide/operator_practice/heterogeneous_computing"}]},"headers":[],"relativePath":"guide/operator_practice/heterogeneous_computing.md","filePath":"guide/operator_practice/heterogeneous_computing.md","outlineHeaders":[{"level":2,"title":"Host侧CPU和Device侧NPU的主要区别","slug":"Host侧CPU和Device侧NPU的主要区别","link":"#Host侧CPU和Device侧NPU的主要区别"},{"level":2,"title":"如何合理安排算子代码","slug":"如何合理安排算子代码","link":"#如何合理安排算子代码"},{"level":2,"title":"算子数据流","slug":"算子数据流","link":"#算子数据流"}],"lastUpdated":1787050286000}'),a={name:"guide/operator_practice/heterogeneous_computing.md"};function l(c,e,r,p,g,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>异构计算<span id="ZH-CN_TOPIC_0000001846719820"></span></h1><p>使用Ascend C进行编程时，会涉及到在两个不同的平台（Host、Device）上开发代码。本章简单介绍Host、Device之间的差异，便于开发者宏观地了解这个异构系统；同时给出算子相关的数据流，结合异构架构的特点，开发者可以进一步了解应该如何合理安排算子代码的执行位置，便于得到更好的性能。</p><h2 id="Host侧CPU和Device侧NPU的主要区别">Host侧CPU和Device侧NPU的主要区别<span id="section5161328183719"></span><a class="header-anchor" href="#Host侧CPU和Device侧NPU的主要区别">​</a></h2><ul><li><p>不同的硬件资源</p><p>CPU是为了执行通用计算任务而设计的，但在处理大量的并行计算（如矩阵乘、批数据处理）时效率不高。NPU是为了加速机器学习和深度学习任务而设计的，它擅长执行大量的并行计算。NPU包含了大量的专用硬件，比如：支持矩阵计算的Cube单元，NPU中一个核可以支持一个时钟周期内完成数据量为16 * 16 * 16、数据类型为float16的乘累加运算；支持向量计算的Vector单元，NPU中一个核可以支持一个时钟周期内完成数据量为128 + 128、数据类型为float16的加法运算。</p></li><li><p>不同的物理内存空间</p><p>Host和Device的物理内存是分离的，通常需要在Host侧内存和Device侧内存之间进行数据交换。</p></li></ul><h2 id="如何合理安排算子代码">如何合理安排算子代码<span id="section1438410488387"></span><a class="header-anchor" href="#如何合理安排算子代码">​</a></h2><p>开发者进行Ascend C算子开发时，可以将Host和Device视为一个协同的异构系统，为每个处理单元分配其擅长的工作。在Host侧推荐执行非计算密集型任务，一般为标量计算任务。在Device侧推荐进行计算密集型任务，利用Device侧NPU的SIMD(Single Instruction Multiple Data)指令可以高效的实现批量数据的矩阵运算、向量运算等。</p><p>Ascend C算子的实现主要包含两个部分：</p><ul><li><p>Host侧Tiling实现</p><p>由于NPU中AI Core内部存储无法完全容纳算子输入输出的所有数据，需要每次搬运一部分输入数据进行计算然后搬出，再搬运下一部分输入数据进行计算，这个过程就称之为Tiling。切分数据的算法称为Tiling算法或者Tiling策略。根据算子的shape等信息来确定数据切分算法相关参数（比如每次搬运的块大小，循环的总次数）的计算程序，称之为Tiling实现，也叫Tiling函数（Tiling Function）。由于Tiling实现中均为标量计算，AI Core并不擅长，所以我们将其独立出来放在Host侧CPU上执行。</p></li><li><p>Device侧核函数（Kernel）实现</p><p>算子核函数（Kernel）实现中，通过解析Host侧传入的Tiling结构体获取Tiling信息，根据Tiling信息控制数据搬入搬出Local Memory的流程；通过调用计算、数据搬运、内存管理、任务同步等API实现算子逻辑。其核心逻辑基本上都为计算密集型任务，适合在Device侧NPU上执行。</p></li></ul><h2 id="算子数据流">算子数据流<span id="section139451246134413"></span><a class="header-anchor" href="#算子数据流">​</a></h2><p>算子执行过程中涉及到Host和Device的数据交换。这里仅针对Tiling参数的传递，给出具体的数据流：Host侧Tiling算法根据算子具体输入输出的信息，完成Tiling参数的计算，并存放在Tiling结构体中；将Host侧的Tiling结构体发送到Device侧，Device侧的算子获取并解析Tiling结构体，基于该信息执行后续的算子计算逻辑。</p><p><strong>图1</strong> 算子Tiling传递数据流<span id="fig1623151118289"></span><br><img src="'+s+'" alt title="算子Tiling传递数据流"></p></article></div>',1)])])}const h=i(a,[["render",l]]);export{u as __pageData,h as default};
